import json
import re
from mosip_auth_sdk import MOSIPAuthenticator
from mosip_auth_sdk.models import DemographicsModel
from dynaconf import Dynaconf


def load_config(path="config.toml"):
    return Dynaconf(settings_files=[path], environments=False)


def load_user_data(filepath):
    """Load user data from a JSON file."""
    with open(filepath, "r", encoding="utf-8") as f:
        return json.load(f)


def wrap_localized(value, language):
    return [{"language": language, "value": value}] if value else None


def validate_and_prepare_fields(user_data):
    """Extract and validate necessary fields, return cleaned values."""
    individual_id = user_data.get("individual_id", "").strip()
    if not individual_id:
        raise ValueError("Missing 'individual_id'.")

    language = user_data.get("language", "eng").strip()
    individual_id_type = user_data.get("individual_id_type", "").strip()
    if not individual_id_type:
        individual_id_type = "UIN" if len(individual_id) == 10 else "VID"

    name = wrap_localized(user_data.get("name"), language)
    gender = wrap_localized(user_data.get("gender"), language)
    full_address = wrap_localized(user_data.get("full_address"), language)

    dob = user_data.get("dob")
    if dob and not re.match(r"\d{4}/\d{2}/\d{2}$", dob):
        raise ValueError("Invalid 'dob' format. Use YYYY/MM/DD.")

    email_id = user_data.get("email_id")

    demographics_data = {}
    if name: demographics_data["name"] = name
    if gender: demographics_data["gender"] = gender
    if full_address: demographics_data["fullAddress"] = full_address
    if dob: demographics_data["dob"] = dob
    if email_id: demographics_data["email"] = email_id

    if not demographics_data:
        raise ValueError("No valid demographic data found in user_data.json.")

    return individual_id, individual_id_type, DemographicsModel(**demographics_data)


def perform_kyc_from_json_file(json_path="user_data.json", config_path="config.toml"):
    """Perform KYC using user data from JSON and decrypt the response."""
    config = load_config(config_path)
    authenticator = MOSIPAuthenticator(config=config)

    user_data = load_user_data(json_path)
    individual_id, individual_id_type, demographics_data = validate_and_prepare_fields(user_data)

    response = authenticator.kyc(
        individual_id=individual_id,
        individual_id_type=individual_id_type,
        demographic_data=demographics_data,
        consent=True,
    )

    response_body = response.json()
    errors = response_body.get("errors") or []

    if errors:
        raise ValueError("\n".join(f"{e.get('errorCode')} : {e.get('errorMessage')}" for e in errors))

    return authenticator.decrypt_response(response_body)
